// Nursing Assisting Practice Test 5. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–4.
import {q, mix} from './q.js';
const DUG='Dugan, Nursing Assisting: A Foundation in Caregiving', ROE='Roe, The Nursing Assistant: Essentials of Holistic Care';
const ROLE='Nursing Assistant Roles and Responsibilities', AP='Anatomy and Physiology', INF='Infection Control/Safety', COMM='Communication/Culture', CARE='Providing and Reporting Care', DIS='Disabilities and Disorders';

export default {
 id:'nursing-assisting-5',
 event:'Nursing Assisting',
 title:'Practice Test 5',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Dugan’s Nursing Assisting: A Foundation in Caregiving and Roe’s The Nursing Assistant',
 plan:[{area:ROLE,weight:6},{area:AP,weight:20},{area:INF,weight:14},{area:COMM,weight:10},{area:CARE,weight:30},{area:DIS,weight:20}],
 questions:mix([
  q(ROLE,'Which 1987 federal law set training and competency standards for nursing assistants in long-term care?','The Omnibus Budget Reconciliation Act (OBRA)',['The Americans with Disabilities Act','The Affordable Care Act','The Social Security Act'],'A','OBRA also created resident rights and requires states to keep a nurse aide registry.',DUG),
  q(ROLE,'A nursing assistant skips a resident’s scheduled repositioning and meals during a busy shift. What is this?','Neglect',['Assault','Defamation','Delegation'],'B','Neglect is failing to provide needed care; it must be reported and can lead to removal from the registry.',DUG),
  q(ROLE,'Two nursing assistants discuss a resident’s diagnosis in a crowded elevator. What is the problem?','It violates the resident’s right to confidentiality',['It is required for good teamwork','It is allowed if no names are used in any setting','It is only a problem if the resident hears it'],'C','Resident information should be discussed only with care team members in private areas.',ROE),
  q(AP,'Which tough band of tissue connects bone to bone at a joint?','Ligament',['Tendon','Cartilage','Fascia'],'D','Ligaments stabilize joints; tendons connect muscle to bone, and both can be injured by twisting.',ROE),
  q(AP,'The elbow and knee bend in only one direction. What type of joint are they?','Hinge joint',['Ball-and-socket joint','Pivot joint','Gliding joint'],'A','Hinge joints allow flexion and extension in one plane, like a door hinge opening and closing.',ROE),
  q(AP,'Which heart chamber receives oxygen-poor blood returning from the body?','Right atrium',['Left atrium','Left ventricle','Aorta'],'B','Blood flows from the right atrium to the right ventricle and then to the lungs to pick up oxygen.',ROE),
  q(AP,'Which blood cells help the blood clot after an injury?','Platelets',['Red blood cells','White blood cells','Plasma cells'],'C','Platelets (thrombocytes) form plugs at injured vessels; a low count increases bleeding.',ROE),
  q(AP,'Which flap of tissue covers the windpipe during swallowing to keep food out of the lungs?','Epiglottis',['Uvula','Tongue','Esophagus'],'D','When the epiglottis does not close well, as after a stroke, residents are at risk of aspiration.',ROE),
  q(AP,'Which organ produces bile to help digest fats?','Liver',['Gallbladder','Pancreas','Stomach'],'A','The liver makes bile and the gallbladder stores and releases it into the small intestine.',ROE),
  q(AP,'Which tubes carry urine from the kidneys to the bladder?','Ureters',['Urethra','Nephrons','Fallopian tubes'],'B','There are two ureters; the single urethra carries urine out of the body.',ROE),
  q(AP,'Which layer at the back of the eye contains the light-sensing cells?','Retina',['Cornea','Iris','Lens'],'C','The retina changes light into nerve signals that travel through the optic nerve to the brain.',ROE),
  q(AP,'Which glands in the skin release oil that keeps skin and hair soft?','Sebaceous glands',['Sweat glands','Salivary glands','Thyroid glands'],'D','Oil production decreases with age, which is one reason older skin becomes dry.',ROE),
  q(AP,'Where are most new blood cells made?','Red bone marrow',['The spleen','The kidneys','The heart'],'A','Red marrow inside bones such as the hips and sternum produces red cells, white cells and platelets.',ROE),
  q(INF,'In the chain of infection, a germ entering the body through a break in the skin is an example of what?','A portal of entry',['A reservoir','A portal of exit','A susceptible host'],'B','Breaking any link in the chain, such as keeping skin intact, helps prevent infection.',DUG),
  q(INF,'Which practice reduces the number and spread of germs during routine care, such as washing hands and using clean linen?','Medical asepsis (clean technique)',['Surgical asepsis (sterile technique)','Sterilization of all equipment','Reverse isolation for every resident'],'C','Medical asepsis is used for everyday care; surgical asepsis keeps items completely free of microorganisms.',DUG),
  q(INF,'Under standard precautions, how should blood and body fluids be treated?','As if they could be infectious for every resident',['Only as infectious if the resident has a known disease','As safe unless they are visible on the skin','As infectious only in the hospital, not in nursing homes'],'D','Standard precautions apply to all residents because infections are not always known.',DUG),
  q(INF,'Which practice keeps a clean supply cart from being contaminated?','Never bring the cart into an isolation room',['Store used linens on the bottom shelf','Leave the cart in a patient’s room for the whole shift','Restock it with items returned from patients’ rooms'],'A','Items taken into a patient room are considered contaminated and are not returned to clean supply.',DUG),
  q(INF,'Why is a stethoscope and blood pressure cuff left in the room of a resident on contact precautions?','To keep the equipment from spreading germs to other residents',['Because it is cheaper than buying new equipment','So the resident can take their own vital signs','Because these items cannot be cleaned at all'],'B','Dedicated equipment stays with the resident, or it is cleaned and disinfected before use elsewhere.',DUG),
  q(INF,'When lifting a heavy object, how should a nursing assistant hold it?','Close to the body, with the knees bent',['At arm’s length, with the knees straight','Above the head, with the back bent','To one side, while twisting at the waist'],'C','Keeping the load close and using the leg muscles protects the back.',DUG),
  q(INF,'A nursing assistant notices a frayed cord on a resident’s lamp. What should be done?','Stop using it and report it so it can be repaired or removed',['Wrap the frayed part in tape and keep using it until the lamp stops working','Ignore it until it stops working','Move it closer to the bed'],'D','Damaged electrical equipment can cause shocks and fires, so it is removed from use and reported.',DUG),
  q(COMM,'Why should a nursing assistant avoid asking “Why” questions, such as “Why didn’t you eat?”','They can sound judgmental and make the resident defensive',['They always produce short yes-or-no answers that give the nurse no useful information','They are not allowed under HIPAA','They make residents talk too much'],'A','Gentle open-ended questions, such as “Tell me about lunch,” encourage sharing.',ROE),
  q(COMM,'A resident says, “I feel off today.” The assistant asks, “Can you tell me what you mean by off?” Which technique is this?','Clarifying',['Giving false reassurance','Changing the subject','Giving advice'],'B','Clarifying helps the assistant understand the resident’s meaning before reporting.',ROE),
  q(COMM,'Before touching a resident for comfort, what should a nursing assistant consider?','The resident’s preferences and cultural views about touch',['Only the assistant’s own comfort with touch','Whether other staff are watching','Whether the family has visited that day'],'C','Touch can be comforting, but some cultures and individuals prefer less of it.',ROE),
  q(COMM,'How should a nursing assistant answer the phone at the nurses’ station?','Give the unit name, their own name and title, and ask how to help',['Say “Hello?” and wait for the caller to speak','Answer with the resident’s name and diagnosis','Let it ring until a nurse is available'],'D','Professional phone greetings identify the location and the speaker.',ROE),
  q(COMM,'A worried resident asks if her surgery will go well. Why is “Don’t worry, everything will be fine” a poor response?','It gives false reassurance and blocks her from sharing feelings',['It is too long and confusing for a worried resident to follow and understand','It shares private medical information','It uses too much medical jargon'],'A','Listening and inviting her to talk about her fears is more helpful.',ROE),
  q(CARE,'Which temperature route usually gives the highest reading?','Rectal',['Oral','Axillary','Temporal'],'B','Rectal readings are about 1 °F higher than oral, and axillary readings about 1 °F lower.',DUG),
  q(CARE,'When taking a tympanic temperature on an adult, how should the ear be pulled?','Up and back',['Down and back','Straight forward','Straight down'],'C','Pulling up and back straightens the adult ear canal; for young children, pull down and back.',DUG),
  q(CARE,'How is an apical pulse taken?','With a stethoscope over the apex of the heart, counted for 1 full minute',['With two fingers on the thumb side of the wrist for 15 seconds, then multiplied by 4','With a thermometer under the tongue','With a cuff on the upper arm'],'D','The apical pulse is heard below the left nipple and is used when the radial pulse is irregular or weak.',DUG),
  q(CARE,'Which bedpan is usually used for a resident with a hip fracture or who cannot raise the hips?','A fracture pan',['A standard bedpan','A urinal','A bedside commode'],'A','A fracture pan is flatter and easier to slide under a resident who cannot lift their hips.',DUG),
  q(CARE,'How should dentures be stored when not in the mouth?','In a labeled denture cup with cool water',['Wrapped in a paper towel on the tray','In hot water to kill germs','Dry in the resident’s drawer'],'B','Hot water can warp dentures, and paper towels may be thrown away by mistake.',DUG),
  q(CARE,'Why should a nursing assistant not cut the toenails of a resident with diabetes?','Small cuts can lead to serious infections because of poor circulation',['Diabetes makes toenails too soft to cut','Toenail cutting is only done by family','It is not needed because toenails stop growing'],'C','A nurse or podiatrist usually trims the nails of residents with diabetes.',DUG),
  q(CARE,'When undressing a resident with a weak left side, which arm comes out of the sleeve first?','The strong right arm',['The weak left arm','Either arm, in any order','Both arms at the same time'],'D','Remove clothing from the strong side first and put it on the weak side first.',DUG),
  q(CARE,'A resident who is blind is about to eat. How can the assistant help?','Describe the food’s location using the numbers on a clock',['Feed every bite to the resident without asking whether help is wanted','Leave the tray and return later','Mix all the foods together'],'A','For example, “Your chicken is at 3 o’clock and your potatoes are at 9 o’clock.”',DUG),
  q(CARE,'A resident after spinal surgery must be turned while keeping the spine straight. Which method is used?','Logrolling with a turning sheet',['Pulling the resident by the arms','Asking the resident to twist','Bending the knees to the chest'],'B','Logrolling moves the body as a single unit and requires two or more staff.',DUG),
  q(CARE,'When walking with a standard walker, what is the correct order?','Move the walker forward, step with the weak leg, then the strong leg',['Step with both legs, then lift the walker','Push the walker while walking quickly','Step with the strong leg first, then move the walker'],'C','The walker should be lifted or rolled a short distance before each step.',DUG),
  q(CARE,'A nursing assistant moves each joint of a resident who cannot move. What is this called?','Passive range of motion',['Active range of motion','Active-assistive exercise','Ambulation training'],'D','In passive ROM, the caregiver moves the joints; in active ROM, the resident moves them.',DUG),
  q(CARE,'A resident uses oxygen through a nasal cannula. Which area should be checked for skin irritation?','Behind the ears and inside the nostrils',['The fingertips and toes on both sides','The lower back and the tailbone area','The palms of the hands and the wrists'],'A','Tubing can rub the skin behind the ears and dry the nostrils; report redness to the nurse.',DUG),
  q(CARE,'When a resident is admitted, why is a list made of their belongings?','To keep a record and help prevent loss or disputes',['To decide which items to throw away','To share with other residents','To determine the resident’s diagnosis'],'B','The resident or family signs the inventory, and valuables may be stored safely.',DUG),
  q(CARE,'During a warm or cold application, how often should the skin usually be checked?','About every 5 minutes',['Only after 2 hours','Only when the resident complains','Never, once it is in place'],'C','Applications usually last no more than 20 minutes; redness, blisters or numbness are reported.',DUG),
  q(CARE,'A resident who has not had a bowel movement for days has liquid stool seeping out. What may this signal?','A fecal impaction',['Normal bowel function','A urinary tract infection','Too much fiber'],'D','Liquid stool can leak around hard, blocked stool; report it to the nurse.',DUG),
  q(DIS,'Which disease damages the protective covering of nerves, causing weakness, numbness and vision problems that come and go?','Multiple sclerosis',['Parkinson disease','Osteoarthritis','Alzheimer disease'],'A','MS often involves flare-ups and remissions; fatigue is common, so rest periods help.',ROE),
  q(DIS,'Which condition is caused by brain damage before or around birth and affects movement and muscle tone?','Cerebral palsy',['Muscular dystrophy','Spina bifida','Multiple sclerosis'],'B','Cerebral palsy does not worsen over time, but needs vary widely from person to person.',ROE),
  q(DIS,'Which genetic condition is caused by an extra copy of chromosome 21?','Down syndrome',['Cystic fibrosis','Sickle cell disease','Hemophilia'],'C','People with Down syndrome may have intellectual disability and higher risk of heart and thyroid problems.',ROE),
  q(DIS,'A spinal cord injury in the neck causes paralysis of the arms, legs and trunk. What is this called?','Quadriplegia (tetraplegia)',['Paraplegia (legs and lower trunk only)','Hemiplegia (one side of the body)','Monoplegia (a single limb only)'],'D','Injuries high in the neck may also affect breathing, because the nerves to the diaphragm start there.',ROE),
  q(DIS,'Which autoimmune disease causes painful, swollen joints on both sides of the body and morning stiffness?','Rheumatoid arthritis',['Osteoarthritis','Gout','Osteoporosis'],'A','In RA, the immune system attacks the joint lining; warm baths and gentle exercise may ease stiffness.',ROE),
  q(DIS,'A resident has chest pain while walking that goes away with rest and nitroglycerin. What is most likely?','Angina pectoris',['A heart attack that is fully over','Pneumonia','A panic attack'],'B','Angina is caused by reduced blood flow to the heart; any chest pain must be reported immediately.',ROE),
  q(DIS,'A resident with kidney failure is on dialysis. Which care instruction is common?','Follow the ordered fluid restriction and measure intake and output',['Push as much fluid as possible','Take blood pressure in the dialysis access arm','Serve extra salty snacks'],'C','Failing kidneys cannot remove extra fluid, so intake is limited and carefully tracked.',ROE),
  q(DIS,'An older man has a weak urine stream and gets up often at night to urinate. What is a common cause?','An enlarged prostate (BPH)',['A kidney stone','Diabetes insipidus','Cystic fibrosis'],'D','Benign prostatic hyperplasia squeezes the urethra and is common in older men.',ROE),
  q(DIS,'After a stroke, a resident understands speech but has great trouble forming words. What is this called?','Expressive aphasia',['Receptive aphasia','Dysphagia','Hemianopia'],'A','Give the resident time, ask yes-or-no questions and use picture boards.',ROE),
  q(DIS,'A resident has a painful rash of blisters in a band on one side of the body. What is most likely?','Shingles (herpes zoster)',['Measles (rubeola) with a full-body rash','Impetigo, a bacterial skin infection','Scabies caused by tiny mites'],'B','Shingles is caused by the chickenpox virus; people who never had chickenpox can catch chickenpox from the blisters.',ROE)
 ],9512)
};
